#!/bin/sh
# Distrust the emSign roots and Sectigo AAA in Chromium-family browsers via policy and the NSS user DB (MKT-3922).
# Run as root at image build after users exist; the headless shell ignores policy. Needs certutil.
# Roots: CN=emSign ECC Root CA - C3,O=eMudhra Inc,OU=emSign PKI,C=US; CN=emSign Root CA - C1,O=eMudhra Inc,OU=emSign PKI,C=US; CN=emSign Root CA - G1,O=eMudhra Technologies Limited,OU=emSign PKI,C=IN; CN=emSign ECC Root CA - G3,O=eMudhra Technologies Limited,OU=emSign PKI,C=IN; CN=AAA Certificate Services,O=Comodo CA Limited,L=Salford,ST=Greater Manchester,C=GB
set -eu

CERTS="



"

json=$(printf '"%s",' $CERTS)
json="{\"CADistrustedCertificates\":[${json%,}]}"
for d in /etc/chromium/policies/managed /etc/opt/chrome/policies/managed /etc/opt/chrome_for_testing/policies/managed; do
    mkdir -p "$d"
    printf '%s\n' "$json" > "$d/emsign-distrust.json"
done

command -v certutil >/dev/null 2>&1 || { echo "chromium-emsign-distrust: certutil not found (install libnss3-tools)" >&2; exit 1; }
tmp=$(mktemp -d)
n=0
for c in $CERTS; do n=$((n + 1)); printf '%s' "$c" | base64 -d > "$tmp/$n.der"; done

homes=$(awk -F: '($3 == 0 || $3 >= 1000) && $6 != "/" && $6 != "/nonexistent" { print $6 }' /etc/passwd)
for home in /etc/skel $homes; do
    [ -d "$home" ] || continue
    db="$home/.pki/nssdb"
    mkdir -p "$db"
    [ -f "$db/cert9.db" ] || certutil -d "sql:$db" -N --empty-password
    i=0
    while [ "$i" -lt "$n" ]; do
        i=$((i + 1))
        certutil -d "sql:$db" -A -t p,p,p -n "distrust $(sha256sum "$tmp/$i.der" | cut -c1-16)" -i "$tmp/$i.der"
    done
    chown -R "$(stat -c %u:%g "$home")" "$home/.pki"
done
rm -rf "$tmp"
echo "chromium-emsign-distrust: $n roots distrusted (policy + NSS: /etc/skel $homes)"
